import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./style/F"
function FeaturesInput() {
  const [features, setFeatures] = useState([]);
  const [featureCount, setFeatureCount] = useState("");
  const navigate = useNavigate();

  const handleGenerate = () => {
    const count = parseInt(featureCount);
    if (count > 0) {
      setFeatures(Array.from({ length: count }, (_, i) => `الميزة ${i + 1}`));
    } else {
      alert("الرجاء إدخال عدد صالح من الخصائص");
    }
  };

  return (
    <div className="features-container">
      <h1 className="features-title">إدخال الخصائص الطبية</h1>
      <p className="features-description">
        قم بتحديد عدد الخصائص الطبية التي ترغب بإدخالها.
      </p>

      <div className="features-input-group">
        <input
          type="number"
          placeholder="عدد الخصائص"
          value={featureCount}
          onChange={(e) => setFeatureCount(e.target.value)}
        />
        <button onClick={handleGenerate}>إنشاء الحقول</button>
      </div>

      <div className="features-list">
        {features.map((f, i) => (
          <input key={i} type="text" placeholder={f} />
        ))}
      </div>

      <div className="features-buttons">
        <button onClick={() => navigate("/samples")} className="btn-back">
          رجوع
        </button>
        <button onClick={() => navigate("/results")} className="btn-next">
          التالي
        </button>
      </div>
    </div>
  );
}
export default FeaturesInput;
